import {UI,discoveryCategories,publicFooter,supplementalPage,catalogueCards,verificationLabel,productFacts,browserStore,parseJSON,featuredProducts,brandLockup} from './public-content.mjs?v=20261030-white-bg';
import {shopMapLinks} from './maps.mjs';
const $=s=>document.querySelector(s), h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
import {Icon as icon} from './icons.mjs';
const categories=discoveryCategories;
const money=(n,c='INR')=>new Intl.NumberFormat(c==='INR'?'en-IN':'en-US',{style:'currency',currency:c,maximumFractionDigits:0}).format(n);
const page=location.pathname.split('/')[1]||'home',entityId=decodeURIComponent(location.pathname.split('/')[2]||''),params=new URLSearchParams(location.search);
const S={user:null,catalogue:[],q:params.get('q')||'',category:params.get('category')||'',currency:['INR','USD'].includes(browserStore.getItem('currency'))?browserStore.getItem('currency'):'INR',lat:params.has('lat')?Number(params.get('lat')):null,lng:params.has('lng')?Number(params.get('lng')):null,area:params.get('area')||'Jammu, India',areaFilter:params.get('area')||'',candidates:[],radius:'5',sort:'price',stock:false,open:false,negotiable:false,min:'',max:'',listings:[],products:[],entity:null,workspace:null,busy:false,error:'',map:false,filters:false,shopQuery:page==='shops'?(params.get('q')||''):'',locationMessage:'',signup:false,ownerShop:'',report:null,edit:null,simulatedMatchesHtml:'',assignmentData:null,assignmentMessage:'',assignmentQuery:'',assignmentShopCount:0,assignmentLimit:12,shopAssignmentsHtml:'',catalogueLoaded:false,homeShopCount:null,resultView:['shops','confirmed','products'].includes(params.get('view'))?params.get('view'):'shops'};
let recent=parseJSON(browserStore.getItem('recent'),[]);recent=Array.isArray(recent)?recent.filter(v=>typeof v==='string'&&v.length<=150).slice(0,6):[];let timer,requestId=0,suggestionIndex=-1;
async function api(path,b){let r;try{r=await fetch('/api/'+path,{...(b?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}:{cache:'no-store'}),signal:AbortSignal.timeout(12000)});}catch{throw new Error(navigator.onLine?'The request timed out or the server is unavailable. Please try again.':'You are offline. Reconnect and try again.');}let d;try{d=await r.json();}catch{throw new Error('The server returned an unreadable response. Reload and try again.');}if(!r.ok)throw Object.assign(new Error(d.error||'Please check the highlighted fields.'),{details:d});return d;}
function toast(message,error=false){const t=$('#toast');if(!t)return;t.innerHTML=icon(error?'alert':'check')+`<span>${h(message)}</span>`;t.className=error?'visible toast-error':'visible';clearTimeout(timer);timer=setTimeout(()=>t.className='',5000);}
function nav(){return `<header class="topbar"><div class="shell nav"><a class="brand" href="/">${brandLockup()}</a><nav aria-label="Main navigation"><a class="${['home','search','products'].includes(page)?'active':''}" href="/">Find a product</a><a href="/shops" class="${page==='shops'?'active':''}" ${page==='shops'?'aria-current="page"':''}>Browse shops</a><a href="/availability" class="${page==='availability'?'active':''}">How it works</a><a href="/for-shops" class="${page==='for-shops'?'active':''}">For shop owners</a></nav><div class="nav-actions"><label class="sr-only" for="currency">Listing currency</label><select id="currency"><option ${S.currency==='INR'?'selected':''}>INR</option><option ${S.currency==='USD'?'selected':''}>USD</option></select>${globalThis.NearbyTheme?.control(icon('sun',20))||''}<a class="button small owner-link" href="/owner">${icon('store',17)}My shop</a><details class="site-menu"><summary><span class="menu-closed">${icon('menu',22)}</span><span class="menu-open">${icon('x',22)}</span><span class="sr-only">Navigation menu</span></summary><div class="menu-panel" role="navigation" aria-label="Compact navigation"><a href="/">${icon('search',20)}Find a product</a><a href="/shops">${icon('store',20)}Browse shops</a><a href="/availability">${icon('info',20)}How availability works</a><a href="/owner">${icon('store',20)}My shop</a><a href="/join">${icon('plus',20)}List your shop</a></div></details></div></div></header>${!navigator.onLine?'<div class="offline" role="status">You’re offline. Reconnect to check current availability. Recent searches are saved on this device.</div>':''}`;}
function footer(){return publicFooter();}
function searchbox(){return `<form id="search-form" class="searchbox">${icon('search',23)}<div class="searchinput"><label for="product-search" class="sr-only">Search electronics</label><input id="product-search" name="q" placeholder="Search a product, model or brand" value="${h(S.q)}" autocomplete="off" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="suggestions" aria-describedby="suggestions-help"><div id="suggestions" class="suggestions" role="listbox" aria-label="Matching catalogue products" hidden></div><span id="suggestions-help" class="sr-only">Type a model or brand. Use the arrow keys and Enter to choose a product.</span><span id="suggestions-status" class="sr-only" aria-live="polite"></span></div><button class="primary">Search ${icon('arrow',18)}</button></form>`;}
function locationControl(){return `<details class="location-control"><summary>${icon('pin',17)}<span>${h(S.area)}</span><span class="tiny">Change</span></summary><div class="location-panel"><button data-action="locate">${icon('locate',17)}Use my location</button><form id="area-form"><label>Or enter area / pincode<input name="area" placeholder="Gandhi Nagar or 180004" required></label><button>Apply area</button></form><p class="muted">${h(S.locationMessage||'Your precise location is used only for this search.')}</p></div></details>`;}
function home(){const featured=featuredProducts(S.catalogue,12),popular=featured.slice(0,3);return '<section class="hero discovery-hero"><div class="shell discovery-intro"><div><span class="eyebrow">ELECTRONICS, CLOSER TO HOME</span><h1>Find it nearby.</h1><p>Compare local prices. Choose your configuration. Find the shop worth visiting.</p></div><div class="hero-search-panel"><h2>What are you looking for?</h2>'+searchbox()+'<div class="hero-location">'+locationControl()+'<span>Jammu, India</span></div>'+(popular.length?'<div class="popular"><span>Explore</span>'+popular.map(p=>'<button data-search="'+h(p.name)+'">'+h(p.name)+' '+icon('up',13)+'</button>').join('')+'</div>':'')+'</div></div><dl class="shell market-stats"><div><dt>'+ (S.grouped?'Product models':'Product variants')+'</dt><dd>'+(S.catalogueLoaded?S.catalogue.length.toLocaleString('en-IN'):'&mdash;')+'</dd></div><div><dt>Local shop listings</dt><dd>'+(S.homeShopCount??'&mdash;')+'</dd></div><div><dt>Categories to explore</dt><dd>'+categories.length+'</dd></div></dl></section><div class="trust-line shell">'+icon('info',18)+'<p>Indicative prices and shop-entered offers are labelled. <a href="/availability">Understand availability before you visit.</a></p></div><section class="shell section"><div class="section-heading"><h2>Browse by category</h2><a href="/shops">Browse Jammu shops '+icon('arrow',17)+'</a></div><div class="category-grid">'+categories.map(([id,name])=>'<a class="category-card" href="/search?category='+id+'"><span class="category-art">'+icon(id,28)+'</span><strong>'+name+'</strong><span>'+icon('arrow',15)+'</span></a>').join('')+'</div></section>'+(recent.length?'<section class="shell recent"><h3>Recently searched</h3><div class="chips">'+recent.map(q=>'<button data-search="'+h(q)+'">'+icon('clock',15)+h(q)+'</button>').join('')+'<button data-action="clear-history">Clear history</button></div></section>':'')+(featured.length?catalogueCards(featured,icon):'')+'<section class="shell section home-how"><div class="section-heading"><h2>From search to storefront</h2><a href="/availability">How availability works '+icon('arrow',17)+'</a></div><div class="steps">'+[['01','Find your model','Search or browse the catalogue, then choose the configuration you need.'],['02','Compare local shops','Check each shop\u2019s price, stock label and last update. Indicative prices are labelled.'],['03','Check before you visit','Contact the shop to confirm, then open its location in Google Maps.']].map(([n,title,text])=>'<div><span class="step-number">'+n+'</span><h3>'+title+'</h3><p>'+text+'</p></div>').join('')+'</div></section><section class="shell home-owner-strip"><div><h2>Run a local shop?</h2><p>Keep your prices and stock up to date so customers can find you.</p></div>'+UI.button('Manage your shop',{href:'/owner',icon:icon('store',18)})+'</section>';}
function empty(title,description,button=''){return UI.empty(title,description,button);}
function skeleton(){return UI.skeleton();}
function directions(s){const urls=shopMapLinks(s);return '<span class="maps-actions">'+(urls.open?'<a class="button primary" href="'+h(urls.open)+'" target="_blank" rel="noopener noreferrer" data-direction="'+h(s.id)+'">'+icon('map',17)+'Open in Google Maps</a>':'<button disabled title="'+h(urls.reason)+'">'+icon('map',17)+'Open in Google Maps</button>')+(urls.directions?'<a class="button" href="'+h(urls.directions)+'" target="_blank" rel="noopener noreferrer" data-direction="'+h(s.id)+'">'+icon('nav',17)+'Get directions</a>':'')+'</span>';}
function card(l,showProduct=true){const a=l.availability;return `<article class="listing-card"><div class="listing-main"><div class="store-icon">${icon(l.product.category_id,29)}</div><div class="listing-name">${showProduct?`<a class="product-link" href="/products/${h(l.product_id)}">${h(l.product.name)}</a>`:''}<a class="shop-name" href="/shops/${h(l.shop_id)}">${h(l.shop.name)} ${l.shop.verification_status==='verified'?icon('shield',17):''}</a><div class="meta"><span>${l.distance==null?'Distance: Not available':l.distance.toFixed(1)+' km away'}</span><span class="${l.open?'open':'muted'}">${l.open==null?'Hours: Not available':l.open?'Open now':'Closed now'}</span><span>${l.rating?l.rating.toFixed(1)+' ('+l.reviewCount+' reviews)':'No reviews yet'}</span></div><p class="address"><span class="badge area-chip">${h(l.shop.area)}</span> ${h(l.shop.city)}</p><p class="muted tiny">${h(verificationLabel(l.shop))}</p></div><div class="price"><strong>${l.price_min==null?'Price: Not available':money(l.price_min,l.currency)}${l.price_max&&l.price_max!==l.price_min?'–'+money(l.price_max,l.currency):''}</strong>${l.negotiable?'<small>Negotiable</small>':''}</div></div><div class="stock-row"><span class="badge ${a.key}">${icon(a.key==='in_stock'?'check':a.key==='stale'?'clock':'alert',14)}${h(a.label)}</span><span class="${a.caution?'caution':'muted'}">${icon('clock',14)}${h(a.confirmation)}</span>${a.stale?`<small class="muted">Last reported: ${h(a.lastReported)}</small>`:''}${a.hidden?'<span class="badge stale">Possibly outdated</span>':''}${a.community?`<small class="community">${h(a.community)}</small>`:''}</div><div class="listing-actions"><details class="rank"><summary>${icon('info',14)}Why this rank?</summary><div class="rank-popover"><strong>Best match: ${l.rank.score}/100</strong>${Object.entries(l.rank.parts).map(([k,v])=>`<div><span>${k} (${{distance:40,freshness:35,rating:15,availability:10}[k]}%)</span><strong>${v.toFixed(1)}</strong></div>`).join('')}<p>Fresh in-stock, low-stock, stale, then out-of-stock groups. Scores order shops within each group. Ratings use a Bayesian average. Changing the sort changes the order.</p></div></details><button class="text-button" data-report="${h(l.id)}">Was it available? / Report</button>${directions(l.shop)}</div></article>`;}
function filters(){return `<aside id="results-filters" class="filters ${S.filters?'show':''}"><h3>${icon('filter',18)}Stock filters<button class="text-button mobile-only" type="button" data-action="filters" aria-label="Close stock filters">${icon('x',18)}</button></h3>${[['stock','In stock or low stock only'],['open','Open now'],['negotiable','Negotiable prices']].map(([k,t])=>`<label class="check"><input type="checkbox" data-filter="${k}" ${S[k]?'checked':''}>${t}</label>`).join('')}<label>Distance<select data-filter="radius" aria-describedby="distance-help" ${S.lat===null?'disabled':''}>${[5,10,25,50].map(n=>`<option value="${n}" ${S.radius==n?'selected':''}>Within ${n} km</option>`).join('')}</select></label><p id="distance-help" class="muted tiny">${S.lat===null?'Choose Use my location to filter by distance.':'Distances are shown only for shops with supplied coordinates.'}</p><label>Minimum price (${S.currency})<input type="number" min="0" data-filter="min" value="${h(S.min)}" placeholder="Any"></label><label>Maximum price (${S.currency})<input type="number" min="0" data-filter="max" value="${h(S.max)}" placeholder="Any"></label><button data-action="reset">Reset filters</button><div class="filter-note">${icon('info',20)}<p>Fresh information matters.<br>Older confirmations come with a caution.</p><a href="/availability">Understand the badges</a></div></aside>`;}
function searchPage(){const p=S.entity,view=S.resultView,title=page==='products'?(p?.name||'Product availability'):S.category?(categories.find(c=>c[0]===S.category)?.[1]||'Electronics'):S.q?`Results for “${S.q}”`:'Electronics near you';return `<div class="shell results-page"><div class="breadcrumb"><a href="/">Home</a><span>›</span><span>${page==='products'?'Product':'Search'}</span></div>${searchbox()}<div class="results-title"><div class="product-heading">${p?`<span class="product-image">${icon(p.category_id,43)}</span>`:''}<div><h1>${h(title)}</h1>${p?`<p>${h(parseJSON(p.specs).summary)} </p>`:''}<div class="row muted">${locationControl()}<span>· ${view==='confirmed'?S.listings.length+' confirmed stock listings':S.products.length+' matching product variants'} ${S.lat===null?'in this area':'within '+S.radius+' km (where coordinates exist)'}</span></div></div></div><div class="view-toggle ${view!=='confirmed'?'is-hidden':''}"><button data-action="list" aria-pressed="${!S.map}">${icon('list',18)}List</button><button data-action="map" aria-pressed="${S.map}">${icon('map',18)}Map</button></div></div>${resultTabs()}${view==='shops'&&S.products.length?`<p class="muted">Matching catalogue: ${S.products.slice(0,3).map(p=>`<a href="/products/${h(p.id)}">${h(p.name)}</a>`).join(', ')}${S.products.length>3?' and more':''}</p>`:''}${view==='shops'?(S.busy?skeleton():S.simulatedMatchesHtml||(S.error?empty('Shop matches could not load',S.error,'<button data-action="retry">Try again</button>'):empty('No catalogue shops match yet',S.assignmentMessage||'Try a model name or browse the shop directory. Stock remains unconfirmed until checked by a shop.','<a class="button" href="/shops">Browse local shops</a>'))):''}${view==='confirmed'?`<div class="results-layout">${filters()}<div><div class="results-toolbar"><button class="mobile-only" data-action="filters" aria-controls="results-filters" aria-expanded="${S.filters}">${icon('filter',17)}Filters</button><span class="muted">Check each shop's evidence label and stock confirmation time.</span><label class="sort">Sort by<select data-filter="sort">${[['best','Best match'],['nearest','Nearest'],['price','Lowest price'],['recent','Recently confirmed']].map(([v,t])=>`<option value="${v}" ${S.sort===v?'selected':''}>${t}</option>`).join('')}</select></label></div>${S.busy?skeleton():S.error?empty('We couldn’t check availability',S.error,'<button data-action="retry">Try again</button>'):!S.listings.length?empty('No confirmed stock listings',S.simulatedMatchesHtml?'No shop-confirmed stock matches these filters. Shop catalogue assignments do not confirm availability.':`No shops nearby list this in ${S.currency}. Try a wider radius or similar products. Currency selection does not convert prices.`,'<button data-results-view="shops">Compare store catalogues</button><button data-action="widen">Search within 50 km</button>'):S.map?'<div id="shop-map" class="map-container" aria-label="Map of shop locations"></div><p class="muted">Map tiles require internet. Only shops with supplied coordinates appear.</p>':`<div class="listing-list">${S.listings.map(l=>card(l,page!=='products')).join('')}</div>`}${p&&S.listings.length?`<p class="muted">Listed prices: ${money(Math.min(...S.listings.map(l=>l.price_min)),S.currency)}–${money(Math.max(...S.listings.map(l=>l.price_max||l.price_min)),S.currency)}</p>`:''}<p class="results-foot">${icon('info',15)}Stock can change. Call the shop before a long trip.</p>${S.products.length&&page!=='products'?`<div class="related"><h3>Matching catalogue products</h3><div class="chips">${S.products.slice(0,16).map(p=>`<a href="/products/${h(p.id)}">${h(p.name)} ${icon('up',14)}</a>`).join('')}</div></div>`:''}</div></div>`:''}</div>`;}
function shopPage(){if(S.busy)return '<div class="shell section">'+skeleton()+'</div>';if(!S.entity)return '<div class="shell section">'+empty('Shop unavailable',S.error||'This shop may be pending approval.')+'</div>';const s=S.entity,hours=(s.hours?JSON.parse(s.hours):{}),photos=JSON.parse(s.photos||'[]'),ls=S.listings.filter(l=>l.currency===S.currency&&l.product.name.toLowerCase().includes(S.shopQuery.toLowerCase()));return `<div class="shell section"><div class="breadcrumb"><a href="/">Home</a><span>›</span><span>Shop details</span></div><div class="shop-header"><div class="shop-avatar">${icon('store',48)}</div><div><span class="badge ${s.verification_status==='verified'?'in_stock':'stale'}">${icon(s.verification_status==='verified'?'shield':'info',16)}${h(verificationLabel(s))}</span><h1>${h(s.name)}</h1><p>${h(s.address)}</p></div><div class="stack">${directions(s)}${!s.sample&&s.phone?`<a class="button" href="tel:${h(s.phone)}">${icon('phone',17)}Call shop</a>`:''}</div></div>${photos.length?`<div class="shop-photos">${photos.map(p=>`<img src="${h(p)}" alt="Shop photo" loading="lazy">`).join('')}</div>`:''}<div class="shop-info"><div><h3>Opening hours</h3><p>${hours.open&&hours.close?h(hours.open)+' - '+h(hours.close)+' IST':'Not available'}</p><p class="muted">Hours information: ${h(hours.closed?.join(', ')||s.hours_source||'Not available')}</p></div><div><h3>Contact</h3><p>${s.sample?'Contact details not available':h(s.phone||'Not available')}</p><p class="muted">No reviews yet.</p></div><div><h3>Location</h3><p>${h(s.area)}, ${h(s.city)}</p><p>${h(s.pincode||'Pincode not available')}</p></div></div>${s.source_url?'<p class="notice"><a class="source-link" href="'+h(s.source_url)+'" target="_blank" rel="noopener noreferrer">Shop information source</a><br>Source check: '+h(s.source_checked_at||'Not available')+'<br>'+h(s.source_check_note||'This listing has not been independently confirmed.')+'</p>':''}<div class="section-heading"><h2>Browse this shop</h2><form id="shop-search"><input name="query" aria-label="Search shop products" placeholder="Search this shop" value="${h(S.shopQuery)}"><button>Search</button></form></div>${S.shopAssignmentsHtml}<div class="section-heading"><h2>Shop-confirmed stock</h2></div><div class="listing-list">${ls.map(l=>card(l)).join('')||empty('No confirmed stock supplied','Try another product or currency.')}</div></div>`;}
function authBox(){return `<section class="shell auth-page auth-split"><div class="auth-visual" role="img" aria-label="Nearbuy shop illustration"><img class="auth-visual-image auth-visual-image--light" src="/images/owner-shop-light.png?v=20261017-2" alt=""><img class="auth-visual-image auth-visual-image--dark" src="/images/owner-shop-dark.png?v=20261017-1" alt=""></div><div class="auth-content"><h1>${S.signup?'Bring your shop to Nearbuy.':'Welcome back.'}</h1><p>Help customers find what’s on your shelves.</p><form id="auth-form" class="panel"><label>Email<input name="email" type="email" autocomplete="username" required></label><div class="form-field"><label for="owner-password">Password</label><span class="password-input"><input id="owner-password" name="password" type="password" autocomplete="${S.signup?'new-password':'current-password'}" minlength="10" maxlength="128" aria-describedby="owner-password-help" required><button type="button" data-password-toggle="owner-password" aria-controls="owner-password" aria-pressed="false">Show</button></span></div><p id="owner-password-help" class="muted">Use at least 10 characters.</p><p class="muted">Your account is stored on this instance. Email verification and password recovery are not available yet.</p><p class="form-error" role="alert"></p><button class="primary">${S.signup?'Create owner account':'Sign in'}</button><button type="button" class="text-button" data-action="auth-toggle">${S.signup?'Already have an account? Sign in':'New here? Create an account'}</button></form><button class="text-button auth-request" data-action="visitor-request">Suggest a shop without an account</button></div></section>`;}
function input(label,name,type='text',value='',extra=''){return UI.input(label,name,{type,value,attributes:extra});}
function shopForm(field=false){return `<form id="shop-form" class="panel" data-field="${field}"><h2>Tell shoppers about your shop</h2><div class="form-grid">${input('Shop name','name','text','','required maxlength="100"')}${input('Phone (optional)','phone','tel','','placeholder="+91…"')}${input('Street address','address','text','','required maxlength="250"')}${input('Area','area','text','','required placeholder="Gandhi Nagar"')}${input('Pincode (optional)','pincode','text','','pattern="[0-9]{6}"')}${input('Google Maps place link (optional)','google_maps_place_url','url')}${input('Latitude (optional)','lat','number','','step="any"')}${input('Longitude (optional)','lng','number','','step="any"')}${input('Opens (IST, optional)','open','time')}${input('Closes (IST, optional)','close','time')}</div><div class="row"><button type="button" data-action="pin-current">${icon('locate',17)}Use shop’s current location</button><button type="button" data-action="pick-pin">${icon('map',17)}Pin shop on map</button></div><p id="pin-status" class="muted tiny">Use the map picker or GPS while at your shop. Coordinates remain editable.</p><fieldset><legend>Categories</legend><div class="chips">${categories.map(([id,t])=>`<label class="check"><input type="checkbox" name="categories" value="${id}">${t}</label>`).join('')}</div></fieldset><label>Shop photo (optional)<input id="shop-photo" type="file" accept="image/*" ${!S.user?'disabled':''}></label><p class="muted tiny">Sign in to add a photo. Photos are resized to 1200 px and compressed before upload.</p><p class="form-error" role="alert"></p><button class="primary">${S.user&&S.ownerAutoApproval?'Register shop':'Submit for review'} ${icon('arrow',17)}</button></form>`;}
function listingForm(shopId,l=null){const choices=availableProducts(shopId);return `<form id="listing-form" class="panel"><h2>${l?'Edit listing':'Add a catalogue product'}</h2><p class="muted">Enter a price and status only after checking the product in your shop.</p><input type="hidden" name="shop_id" value="${h(shopId)}">${l?`<input type="hidden" name="id" value="${h(l.id)}"><h3>${h(l.product.name)}</h3>`:`<div class="form-field"><label for="catalogue-filter">Find a catalogue product</label><input id="catalogue-filter" placeholder="Filter by model or brand" autocomplete="off"><label for="product-options">Select a product variant</label><select name="product_id" id="product-options" size="5" required>${choices.map(p=>`<option value="${h(p.id)}">${h(p.name)}</option>`).join('')}</select><p class="muted tiny">Products already listed in this shop are excluded.</p></div>`}<div class="form-grid">${input('Price','price_min','number',l?.price_min||'','required min="0.01" step="0.01"')}${input('Maximum price (optional)','price_max','number',l?.price_max||'','min="0.01" step="0.01"')}<label>Currency<select name="currency"><option ${l?.currency!=='USD'?'selected':''}>INR</option><option ${l?.currency==='USD'?'selected':''}>USD</option></select></label><label>Availability<select name="status_reported">${[['in_stock','In stock'],['low_stock','Low stock'],['out_of_stock','Out of stock']].map(([v,t])=>`<option value="${v}" ${l?.status_reported===v?'selected':''}>${t}</option>`).join('')}</select></label>${input('Quantity (optional)','quantity','number',l?.quantity??'','min="0" step="1"')}<label class="check"><input type="checkbox" name="negotiable" ${l?.negotiable?'checked':''}>Price is negotiable</label></div><p class="form-error" role="alert"></p><button class="primary">${l?'Save and confirm':'Add product'} ${icon('check',17)}</button></form>`;}
function owner(){if(S.visitorSubmitted)return '<section class="shell section"><h1>Pending approval</h1><p>Your shop request has been received. It will stay hidden publicly until reviewed.</p><a class="button" href="/shops">Browse shops</a></section>';if(!S.user)return S.visitorRequest?'<section class="shell section"><h1>Suggest a real shop</h1><p>Only share publicly available information. Leave anything unknown empty.</p>'+shopForm()+'</section>':authBox();if(S.busy)return '<section class="shell section">'+skeleton()+'</section>';const d=S.workspace;if(!d)return '<section class="shell section">'+empty('Couldn’t load your workspace',S.error,'<button data-action="workspace-retry">Try again</button>')+'</section>';const s=d.shops.find(s=>s.id===S.ownerShop)||d.shops[0],ls=d.listings.filter(l=>l.shop_id===s?.id),fresh=ls.filter(l=>!l.availability.stale).length;return `<section class="shell section workspace"><div class="section-heading"><div><span class="eyebrow">YOUR SHOP WORKSPACE</span><h1>Keep your shelves in the picture.</h1><p class="muted">${h(S.user.email)} · ${h(S.user.role)}</p></div><button data-action="logout">Sign out</button></div>${!s||page==='join'?shopForm():`<div class="panel shop-select"><label>Shop<select id="owner-shop">${d.shops.map(v=>`<option value="${h(v.id)}" ${v.id===s.id?'selected':''}>${h(v.name)}</option>`).join('')}</select></label><span class="badge ${s.status==='active'?'in_stock':'low_stock'}">${h(s.status)}</span><a href="/join">Add another shop</a></div>${s.status!=='active'?`<p class="notice">${s.status==='pending'?'Your shop is awaiting admin approval. You can prepare listings; they appear in search after approval.':'Your shop is suspended. Contact your administrator.'}</p>`:''}<div class="stats"><div><strong>${ls.length}</strong><span>Product listings</span></div><div><strong>${ls.length?Math.round(fresh/ls.length*100):0}%</strong><span>Confirmed in last 7 days</span></div><div><strong>${d.counts?.find(c=>c.shop_id===s.id&&c.kind==='views')?.count||0}</strong><span>Shop views (7 days)</span></div><div><strong>${d.counts?.find(c=>c.shop_id===s.id&&c.kind==='direction_taps')?.count||0}</strong><span>Directions (7 days)</span></div></div>${ls.some(l=>l.availability.stale)?'<p class="notice">Some products have not been checked in seven days. Review them and confirm accurate stock.</p>':''}${s.review_reason?'<p class="notice">Admin review: '+h(s.review_reason)+'</p>':''}<div class="section-heading"><div><h2>Your products</h2><p class="muted">Review changed items first, then confirm everything else.</p></div><button class="primary" data-confirm-all="${h(s.id)}" ${['on_hold','deactivated','rejected'].includes(s.status)?'disabled':''}>${icon('check',18)}Confirm all still accurate</button></div><div class="owner-list">${ls.map(l=>`<article class="panel"><div class="section-heading"><div><h3>${h(l.product.name)}</h3><p>${money(l.price_min,l.currency)} · ${h(l.availability.confirmation)}</p><span class="badge ${l.availability.key}">${h(l.availability.label)}</span></div><button data-edit="${h(l.id)}">Edit price / details</button></div><div class="status-controls">${[['in_stock','In stock'],['low_stock','Low stock'],['out_of_stock','Out of stock']].map(([v,t])=>`<button class="${l.status_reported===v?'selected':''}" data-confirm="${h(l.id)}" data-status="${v}" data-shop="${h(s.id)}">${icon(v==='in_stock'?'check':'clock',16)}${t}</button>`).join('')}</div><details class="owner-rank"><summary>How my listing ranks: ${l.rank.score}/100</summary><p>Distance ${l.rank.parts.distance.toFixed(1)}/40 · Freshness ${l.rank.parts.freshness.toFixed(1)}/35 · Rating ${l.rank.parts.rating.toFixed(1)}/15 · Availability ${l.rank.parts.availability.toFixed(1)}/10.</p><p>Confirming accurate stock daily improves freshness. Fresh available listings appear ahead of stale listings.</p></details></article>`).join('')||empty('Your first product starts here','Choose a shared catalogue product below.')}</div>${listingForm(s.id)}`}</section>`;}
const staticContent={about:['Local discovery, with fewer wasted trips.','Nearbuy helps people in Jammu choose which electronics shop to visit. Compare stock confirmation times, prices, and distance. Shops and shoppers contribute information; stock can change between a confirmation and your visit.','We are starting with electronics in one city. Product variants may be user supplied and unverified. Shop directory records include source links. Admin-approved catalogue assignments are not stock confirmations.'],availability:['What does “available” really mean?','Shop catalogues show admin-approved product assignments, not confirmed availability. The Confirmed stock view contains actual shop reports. A fresh confirmation is useful evidence, and never a guarantee.','0–48 hours: show the shop’s reported status. 48 hours–7 days: show that status with an older-confirmation caution. Over 7 days: “Not recently confirmed”, with the last reported status below it. Over 30 days: hide from default search; show “Possibly outdated” on the shop page.','A customer “available” report adds a separate community confirmation. It never resets the owner’s timestamp. Two independent out-of-stock reports within 48 hours flag the listing until the owner confirms again. One device or IP counts once.','Best match uses distance 40%, freshness 35%, Bayesian rating 15%, and availability 10%. Fresh in-stock listings rank ahead of low-stock, stale, and out-of-stock groups. “Why this rank?” shows each actual contribution. Nearest, price and recent sorts retain availability groups so an out-of-stock result cannot jump ahead of fresh in-stock results.'],privacy:['Your location is for finding a shop.','Precise search coordinates are used for the request and are not saved to your account. Area and recent search preferences stay in browser storage. Search text, result counts, and direction taps are stored without a visitor profile.','Reports use hashed session and network identifiers to limit duplicates and abuse. Owners’ account emails, hashed passwords, shop information, stock changes, and sessions are stored in the local SQLite database. Passwords use scrypt; session tokens are hashed.','This installation stores account and shop information securely on its host. No advertising trackers are installed. Contact your workspace administrator for data correction or removal. Clear recent searches from the home page.'],terms:['Check before making a long trip.','Listings are supplied by shops and shoppers. Availability, prices, opening hours, and distance estimates can change. Confirm important details with the shop. INR and USD selection filters listing currencies; it does not convert prices.','Only submit information you are authorized to share. Do not create misleading listings or abusive reports. Administrators may suspend shops and archive inaccurate records.','Unconfirmed source listings are leads for contacting shops. They are not evidence that a model is available locally.'],contact:['Need to correct something?','For a listing issue, use “Was it available? / Report” on the listing. Shop owners can correct their products immediately from My shop.','For account or registration help, contact your platform administrator. For product enquiries, use the contact details on the store page.'], 'for-shops':['Your next customer is already nearby.','Help people find the products you have in your physical shop. Create an account, submit your shop, then add products from the shared electronics catalogue. Your shop appears in search once its registration is active. Registration is separate from identity or stock verification.','Once your products are listed, one tap confirms a status. “Confirm all still accurate” refreshes every listing after you have checked changes. Fresh, accurate listings rank higher.','Prices can be fixed, a range, or negotiable. INR and USD are stored per listing. There are no checkout, delivery, payment, or reservation flows.']};
function staticPage(){const extra=supplementalPage(page);if(extra)return extra;const c=staticContent[page];if(!c)return '<section class="shell section">'+empty('Page not found','Return home to find a product.','<a class="button" href="/">Back home</a>')+'</section>';return `<section class="shell prose section"><span class="eyebrow">${h(page.replace('-',' '))}</span><h1>${h(c[0])}</h1>${c.slice(1).map(p=>`<p>${h(p)}</p>`).join('')}${page==='for-shops'?'<a class="button primary" href="/join">List your shop →</a>':''}</section>`;}
function render(){let html=['catalogues','simulation'].includes(page)?'<section class="shell section simulation-page"><h1>Store catalogues</h1><div id="simulation-content"><p>Loading store catalogues...</p></div></section>':page==='home'?home():['search','products'].includes(page)?searchPage():page==='shops'&&!entityId?directoryPage():page==='shops'?shopPage():['owner','join'].includes(page)?owner():staticPage();if(page==='products'&&S.entity)html+=productFacts(S.entity);if(page==='search'&&S.resultView==='products'){const products=page==='home'?featuredProducts(S.catalogue,12):S.products,limit=S.catalogueLimit||24;if(products.length)html+=catalogueCards(products.slice(0,limit),icon)+(products.length>limit?'<div class="shell row"><button data-action="more-products">Show more products ('+(products.length-limit)+' remaining)</button></div>':'');}$('#app').innerHTML=nav()+`<main id="main" class="${['owner','join'].includes(page)?'':'buyer-main'}">${html}</main>`+footer();if(S.map&&$('#shop-map'))drawMap($('#shop-map'),S.listings.map(l=>l.shop));}
async function loadSearch(){const rid=++requestId;S.busy=true;S.error='';S.simulatedMatchesHtml='';S.assignmentData=null;S.assignmentMessage='';S.assignmentShopCount=0;render();const p=new URLSearchParams({q:page==='products'?'':S.q,currency:S.currency,radius:S.radius,sort:S.sort});if(S.lat!==null&&S.lng!==null){p.set('lat',S.lat);p.set('lng',S.lng);}if(S.areaFilter)p.set('area',S.areaFilter);if(page==='products')p.set('product',entityId);if(S.category)p.set('category',S.category);for(const k of ['stock','open','negotiable','min','max'])if(S[k])p.set(k,String(S[k]));try{const simulatedQuery=new URLSearchParams();if(page==='products')simulatedQuery.set('product',entityId);else if(S.q)simulatedQuery.set('q',S.q);if(S.category)simulatedQuery.set('category',S.category);if(S.areaFilter)simulatedQuery.set('area',S.areaFilter);if(S.lat!==null&&S.lng!==null){simulatedQuery.set('lat',S.lat);simulatedQuery.set('lng',S.lng);simulatedQuery.set('radius',S.radius);}const [d,simulation]=await Promise.all([api('search?'+p),api('simulation?'+simulatedQuery).catch(error=>({available:false,message:error.message}))]);if(rid!==requestId)return;S.listings=d.listings;S.products=d.products;S.candidates=d.shops||[];S.assignmentMessage=simulation?.message||'';if(simulation?.available&&simulation.rows?.length){const {simulationSearchMatches}=await import('./simulation.mjs?v=20261017-buyer-3');if(rid!==requestId)return;S.assignmentData=simulation;S.assignmentQuery=simulatedQuery.toString();S.assignmentShopCount=simulation.matching_shop_ids?.length??new Set(simulation.rows.map(r=>r.shop.id)).size;S.simulatedMatchesHtml=simulationSearchMatches(simulation,simulatedQuery,{limit:S.assignmentLimit});}}catch(e){S.error=e.message;}finally{if(rid===requestId){S.busy=false;render();}}}
async function loadWorkspace(){S.busy=true;S.error='';render();try{S.workspace=await api('owner');}catch(e){S.error=e.message;}finally{S.busy=false;render();}}
function search(q){q=q.trim();recent=[q,...recent.filter(r=>r!==q)].filter(Boolean).slice(0,6);browserStore.setItem('recent',JSON.stringify(recent));const p=new URLSearchParams({q});if(S.lat!==null&&S.lng!==null){p.set('lat',S.lat);p.set('lng',S.lng);}if(S.areaFilter)p.set('area',S.areaFilter);location.href='/search?'+p;}
function formObject(form){const f=new FormData(form),b=Object.fromEntries(f);b.negotiable=f.has('negotiable');b.categories=f.getAll('categories');return b;}
function openModal(html){const m=$('#modal');m.innerHTML=UI.dialog(html);m.removeAttribute('aria-label');m.removeAttribute('aria-labelledby');const title=m.querySelector('h1,h2');if(title){title.id='dialog-title';m.setAttribute('aria-labelledby',title.id);}else m.setAttribute('aria-label','Listing details');m.showModal();}
async function compressed(file){if(!file.type.startsWith('image/'))throw new Error('Choose an image file.');const image=await createImageBitmap(file),scale=Math.min(1,1200/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();return canvas.toDataURL('image/jpeg',.75);}
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;if(form.id==='simulation-filters'||form.id.startsWith('admin-')||form.id.startsWith('catalog-')||form.id.startsWith('shop-model-'))return;e.preventDefault();const b=formObject(form),err=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"],button:not([type])');if(err)err.textContent='';try{if(form.id==='search-form')return search(b.q);if(form.id==='area-form'){S.lat=null;S.lng=null;S.area=b.area;S.areaFilter=b.area.trim().toLowerCase()==='jammu'?'':b.area.trim();S.locationMessage='Filtering by the published area or pincode. Distances need real coordinates.';if(['search','products'].includes(page))loadSearch();else render();return;}if(form.id==='directory-filter'){S.directoryQuery=b.query;S.directoryArea=b.area;return render();}if(form.id==='shop-search'){S.shopQuery=b.query;await loadShopAssignments();return render();}if(button)button.disabled=true;form.setAttribute('aria-busy','true');
 if(form.id==='auth-form'){await api(S.signup?'auth/signup':'auth/login',b);location.href='/owner';}
 if(form.id==='shop-form'){const file=$('#shop-photo')?.files?.[0];if(file){const r=await api('upload',{image:await compressed(file)});b.photos=[r.url];}const submitted=await api('shops',b);if(!S.user){S.visitorSubmitted=true;render();return;}toast(submitted.shop.status==='active'?'Your shop is active. Add your products to get started.':'Shop submitted for review.');if(page==='join')location.href='/owner';else await loadWorkspace();}
 if(form.id==='listing-form'){await api(b.id?'listing-edit':'listings',b);$('#modal').close();toast('Listing saved and confirmed.');await loadWorkspace();}
 if(form.id==='report-form'){await api('reports',{listing_id:S.report.id,kind:b.kind});$('#modal').close();toast('Thank you. Your report has been counted.');if(page==='shops'){const d=await api('shops/'+entityId);S.listings=d.listings;render();}else await loadSearch();}
 }catch(ex){const msg=ex.details?.errors?ex.details.errors.map(r=>`Row ${r.row}: ${r.error}`).join('\n'):ex.message;if(err){err.textContent=msg;err.tabIndex=-1;err.focus();}else{S.locationMessage=msg;toast(msg,true);}}finally{form.setAttribute('aria-busy','false');if(button)button.disabled=false;}});
document.addEventListener('change',e=>{const t=e.target;if(t.id==='currency'){S.currency=t.value;browserStore.setItem('currency',t.value);if(['search','products'].includes(page))loadSearch();else render();}if(t.dataset.filter){S.resultView='confirmed';S[t.dataset.filter]=t.type==='checkbox'?t.checked:t.value;loadSearch();}if(t.id==='owner-shop'){S.ownerShop=t.value;render();}});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='product-search'){S.q=t.value;suggestionIndex=-1;const box=$('#suggestions');if(!box)return;const query=t.value.trim().toLowerCase(),list=query?S.catalogue.filter(p=>(p._search||[p.name,...(Array.isArray(parseJSON(p.aliases,[]))?parseJSON(p.aliases,[]):[])].join(' ').toLowerCase()).includes(query)).slice(0,7):[];box.innerHTML=list.map((p,i)=>'<button type="button" role="option" tabindex="-1" id="suggestion-'+i+'" aria-selected="false" data-product="'+h(p.id)+'">'+icon(p.category_id,20)+'<span>'+h(p.name)+'<small>'+h(parseJSON(p.specs).summary||p.brand)+'</small></span>'+icon('arrow',17)+'</button>').join('');box.hidden=!list.length;t.setAttribute('aria-expanded',String(!box.hidden));t.removeAttribute('aria-activedescendant');const status=$('#suggestions-status');if(status)status.textContent=list.length?list.length+' product suggestions. Use arrow keys to choose.':'';}if(t.id==='catalogue-filter'){const shop=$('#listing-form [name=shop_id]')?.value;$('#product-options').innerHTML=availableProducts(shop).filter(p=>p.name.toLowerCase().includes(t.value.toLowerCase())).map(p=>'<option value="'+h(p.id)+'">'+h(p.name)+'</option>').join('')||'<option value="">No unlisted products match</option>';}});
document.addEventListener('focusout',e=>{if(e.target.id==='product-search'&&!e.relatedTarget?.closest?.('#suggestions'))closeSuggestions();});
document.addEventListener('pointerdown',e=>{if(e.target.closest?.('#suggestions [role=option]'))e.preventDefault();});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&$('#product-search')){e.preventDefault();$('#product-search').focus();return;}if(e.key==='Escape'){const menu=$('.site-menu[open]');if(menu){menu.open=false;menu.querySelector('summary')?.focus();}closeSuggestions();}if(e.target.id!=='product-search')return;const box=$('#suggestions');if(!box||box.hidden)return;const options=[...box.querySelectorAll('[role=option]')];if(!options.length)return;if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();suggestionIndex=suggestionIndex<0?(e.key==='ArrowDown'?0:options.length-1):(suggestionIndex+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>o.setAttribute('aria-selected',String(i===suggestionIndex)));e.target.setAttribute('aria-activedescendant',options[suggestionIndex].id);options[suggestionIndex].scrollIntoView?.({block:'nearest'});}if(e.key==='Enter'&&suggestionIndex>=0){e.preventDefault();location.href='/products/'+encodeURIComponent(options[suggestionIndex].dataset.product);}});
document.addEventListener('click',async e=>{if(!e.target.closest('.searchbox'))closeSuggestions();const menu=$('.site-menu[open]');if(menu&&!e.target.closest('.site-menu'))menu.open=false;const t=e.target.closest('button,a');if(!t)return;try{if(t.dataset.passwordToggle){const field=document.getElementById(t.dataset.passwordToggle);if(field){const show=field.type==='password';field.type=show?'text':'password';t.textContent=show?'Hide':'Show';t.setAttribute('aria-pressed',String(show));}return;}if(t.dataset.product){location.href='/products/'+encodeURIComponent(t.dataset.product);return;}if(t.dataset.resultsView){S.resultView=t.dataset.resultsView;const url=new URL(location.href);url.searchParams.set('view',S.resultView);globalThis.history?.replaceState?.(null,'',url);render();$('[data-results-view="'+S.resultView+'"]')?.focus();return;}if(t.dataset.action==='more-products'){S.catalogueLimit=(S.catalogueLimit||24)+24;render();return;}if(t.dataset.search!==undefined)return search(t.dataset.search);if(t.dataset.direction)api('direction-tap',{shop_id:t.dataset.direction}).catch(()=>{});if(t.dataset.report){S.report=S.listings.find(l=>l.id===t.dataset.report);openModal(`<h2>Help the next shopper</h2><p>${h(S.report.product.name)} at ${h(S.report.shop.name)}</p><form id="report-form"><fieldset><legend>What did you find?</legend>${[['available','Yes, it was available'],['out_of_stock','I went, it was out of stock'],['wrong_price','The price was different'],['closed','Shop closed or moved'],['wrong_product','Wrong product']].map(([v,l],i)=>`<label class="check"><input type="radio" name="kind" value="${v}" ${!i?'checked':''}>${l}</label>`).join('')}</fieldset><p class="muted tiny">Your report never changes the shop’s confirmation time. Duplicate device/network reports count once.</p><p class="form-error" role="alert"></p><button class="primary">Submit report</button></form>`);return;}if(t.dataset.edit){const l=S.workspace.listings.find(l=>l.id===t.dataset.edit);return openModal(listingForm(l.shop_id,l));}if(t.dataset.confirm||t.dataset.confirmAll){t.disabled=true;await api('confirm',{shop_id:t.dataset.shop||t.dataset.confirmAll,listing_id:t.dataset.confirm,status:t.dataset.status});toast('Stock confirmed. Timestamp refreshed.');await loadWorkspace();}const a=t.dataset.action;if(a==='directory-reset'){S.directoryArea='';S.directoryQuery='';render();return;}if(a==='visitor-request'){S.visitorRequest=true;render();}if(a==='back-top')window.scrollTo({top:0,behavior:'smooth'});if(a==='more-shops'){S.assignmentLimit=64;if(S.assignmentData){const {simulationSearchMatches}=await import('./simulation.mjs?v=20261017-buyer-3');S.simulatedMatchesHtml=simulationSearchMatches(S.assignmentData,new URLSearchParams(S.assignmentQuery),{limit:S.assignmentLimit});render();$('.simulated-search')?.focus();}return;}if(a==='clear-history'){recent=[];browserStore.removeItem('recent');render();}if(a==='map'||a==='list'){S.map=a==='map';render();}if(a==='filters'){S.filters=!S.filters;render();if(S.filters)$('#results-filters input')?.focus();else $('.results-toolbar [data-action=filters]')?.focus();}if(a==='reset'){Object.assign(S,{stock:false,open:false,negotiable:false,min:'',max:'',radius:'5',sort:'price',area:'Jammu, India',areaFilter:'',lat:null,lng:null});loadSearch();}if(a==='widen'){S.radius='50';loadSearch();}if(a==='retry')loadSearch();if(a==='workspace-retry')loadWorkspace();if(a==='auth-toggle'){S.signup=!S.signup;render();}if(a==='logout'){await api('auth/logout',{});location.href='/owner';}if(a==='close-modal')$('#modal').close();if(a==='pick-pin'){openModal('<h2>Pin your shop in Jammu</h2><p>Click the map to set coordinates. Use + and − to zoom.</p><div id="pin-map" class="map-container"></div>');drawMap($('#pin-map'),[],(lat,lng)=>{const f=$('#shop-form');f.elements.lat.value=lat.toFixed(6);f.elements.lng.value=lng.toFixed(6);$('#pin-status').textContent='Map pin selected.';$('#modal').close();});}if(a==='locate'||a==='pin-current'){if(!navigator.geolocation)throw new Error('Location is unavailable. Enter an area or coordinates.');t.disabled=true;navigator.geolocation.getCurrentPosition(p=>{if(a==='pin-current'){const f=$('#shop-form');f.elements.lat.value=p.coords.latitude.toFixed(6);f.elements.lng.value=p.coords.longitude.toFixed(6);$('#pin-status').textContent='GPS coordinates selected.';t.disabled=false;}else{S.lat=p.coords.latitude;S.lng=p.coords.longitude;S.areaFilter='';S.area='Your current location';S.locationMessage='Location is used for this search only.';if(['search','products'].includes(page))loadSearch();else render();}},()=>{t.disabled=false;toast('Location unavailable. Enter your area/pincode, or pin the shop on the map.');},{timeout:10000,maximumAge:60000});}}catch(ex){toast(ex.message,true);t.disabled=false;}});
function drawMap(container,shops,pick){const unique=[...new Map(shops.filter(s=>Number.isFinite(s.lat)&&Number.isFinite(s.lng)).map(s=>[s.id,s])).values()];if(!unique.length&&!pick){container.innerHTML='<div class="empty">'+icon('map',32)+'<h3>No confirmed map pins</h3><p>These shops have no supplied coordinates. Use the published Google Maps links on their shop pages.</p></div>';return;}let z=13,lat=unique[0]?.lat??32.7266,lng=unique[0]?.lng??74.857;function world(a,b){const n=2**z;return {x:(b+180)/360*n*256,y:(1-Math.asinh(Math.tan(a*Math.PI/180))/Math.PI)/2*n*256};}function inverse(x,y){const n=2**z;return {lng:x/256/n*360-180,lat:Math.atan(Math.sinh(Math.PI*(1-2*y/256/n)))*180/Math.PI};}function draw(){const w=container.clientWidth||600,ht=440,c=world(lat,lng),left=c.x-w/2,top=c.y-ht/2;let tiles='';for(let x=Math.floor(left/256);x<=Math.floor((left+w)/256);x++)for(let y=Math.floor(top/256);y<=Math.floor((top+ht)/256);y++)tiles+=`<img alt="" draggable="false" src="https://tile.openstreetmap.org/${z}/${x}/${y}.png" style="left:${x*256-left}px;top:${y*256-top}px" width="256" height="256">`;container.innerHTML=`<div class="map-tiles">${tiles}</div>${unique.map(s=>{const p=world(s.lat,s.lng);return `<a class="map-marker" style="left:${p.x-left}px;top:${p.y-top}px" href="/shops/${h(s.id)}" title="${h(s.name)}" aria-label="${h(s.name)}">${icon('store',19)}</a>`;}).join('')}<div class="map-controls"><button type="button" data-zoom="1" aria-label="Zoom in">${icon('plus',20)}</button><button type="button" data-zoom="-1" aria-label="Zoom out">${icon('minus',20)}</button><button type="button" data-pan="-1,0" aria-label="Pan left">${icon('back',20)}</button><button type="button" data-pan="1,0" aria-label="Pan right">${icon('arrow',20)}</button><button type="button" data-pan="0,-1" aria-label="Pan up">${icon('top',20)}</button><button type="button" data-pan="0,1" aria-label="Pan down">${icon('top',20)}</button></div><a class="map-attribution" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">© OpenStreetMap contributors</a>`;container.onclick=e=>{const zoom=e.target.closest('[data-zoom]'),pan=e.target.closest('[data-pan]');if(zoom){z=Math.max(10,Math.min(18,z+Number(zoom.dataset.zoom)));draw();}else if(pan){const [x,y]=pan.dataset.pan.split(',').map(Number),p=inverse(c.x+x*128,c.y+y*128);lat=p.lat;lng=p.lng;draw();}else if(pick&&!e.target.closest('a,button')){const r=container.getBoundingClientRect(),p=inverse(left+e.clientX-r.left,top+e.clientY-r.top);pick(p.lat,p.lng);}};}draw();if(unique.length)container.insertAdjacentHTML("afterend",'<div class="map-shop-links">'+unique.map(s=>'<div class="panel"><strong>'+h(s.name)+'</strong>'+directions(s)+'</div>').join('')+'</div>');}
window.addEventListener('online',()=>{toast('You’re back online. Refresh availability before visiting.');render();});window.addEventListener('offline',render);
async function init(){let runtime;try{const response=await fetch('/api/runtime',{cache:'no-store',signal:AbortSignal.timeout(2500)});runtime=await response.json();if(['127.0.0.1','localhost'].includes(location.hostname)&&['3000','3001','3002','3005','3006','3007','3008','3009'].includes(location.port)&&(response.status===404||runtime.features?.adminDesign!==true)){const updated=new URL(location.href);updated.port='3012';location.replace(updated.href);return;}}catch{}S.grouped=runtime?.features?.groupedCatalog===true;if(document.querySelector('meta[name=admin-base]')){const {mountAdmin}=await import('./admin.mjs?v=20261017-nearbuy-1');return mountAdmin();}if(S.grouped&&(['search','products','catalogues','simulation'].includes(page)||page==='shops'&&entityId)){const {mountCatalogue}=await import('./catalog-ui.mjs?v=20261017-buyer-3');await mountCatalogue({api,nav,footer,page,entityId});return;}if(['catalogues','simulation'].includes(page)){render();const {mountSimulation}=await import('./simulation.mjs?v=20261017-buyer-3');await mountSimulation();return;}render();const results=await Promise.allSettled([api('session'),['home','search','products','owner','join'].includes(page)?S.grouped&&page==='home'?api('models').then(d=>d.models):api('catalogue'):Promise.resolve([]),page==='home'?api('shops'):Promise.resolve(null)]);if(results[0].status==='fulfilled'){S.user=results[0].value.user;S.ownerAutoApproval=results[0].value.ownerAutoApproval===true;}if(results[1].status==='fulfilled'){S.catalogue=(results[1].value||[]).map(p=>({...p,_search:[p.name,...(Array.isArray(parseJSON(p.aliases,[]))?parseJSON(p.aliases,[]):[])].join(' ').toLowerCase()}));S.catalogueLoaded=true;}if(results[2]?.status==='fulfilled'&&results[2].value?.shops)S.homeShopCount=results[2].value.shops.length;if(S.grouped&&['owner','join'].includes(page)&&S.user){const {mountShopModels}=await import('./shop-model-ui.mjs?v=20261017-buyer-3');await mountShopModels({api,nav,footer});return;}if(page==='join')S.signup=true;if(page==='products'){try{const d=await api('products/'+encodeURIComponent(entityId));S.entity=d.product;S.listings=d.listings;}catch(e){S.error=e.message;}}if(['search','products'].includes(page))await loadSearch();else if(page==='shops'&&!entityId){try{S.directory=(await api('shops')).shops;}catch(e){S.error=e.message;}render();}else if(page==='shops'){S.busy=true;render();try{const d=await api('shops/'+encodeURIComponent(entityId));S.entity=d.shop;S.listings=d.listings;await loadShopAssignments();api('shop-view',{shop_id:entityId}).catch(()=>{});}catch(e){S.error=e.message;}S.busy=false;render();}else if(['owner','join'].includes(page)&&S.user)await loadWorkspace();else render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
init();

function directoryPage(){const shops=(S.directory||[]).filter(s=>(!S.directoryArea||s.area===S.directoryArea)&&(!S.directoryQuery||(s.name+' '+s.area+' '+(s.pincode||'')).toLowerCase().includes(S.directoryQuery.toLowerCase())));return '<section class="shell buyer-page"><header class="buyer-page-heading"><div><span class="eyebrow">THE JAMMU SHOP DIRECTORY</span><h1>Find your local electronics shop.</h1><p>Browse published shop listings and explore each store\u2019s catalogue.</p></div><span class="directory-count">'+shops.length+' shops</span></header><form id="directory-filter" class="directory-filter panel">'+UI.input('Shop name or pincode','query',{value:S.directoryQuery||'',attributes:'placeholder="Search shops"'})+UI.select('Area','area',[{value:'',label:'All areas'},...[...new Set((S.directory||[]).map(s=>s.area))].sort().map(value=>({value,label:value}))],{value:S.directoryArea||''})+'<div class="row">'+UI.button('Apply filters',{type:'submit',kind:'primary'})+UI.button('Reset',{attributes:'data-action="directory-reset"'})+'</div></form><div class="directory-grid">'+shops.map(s=>UI.card('<span class="badge area-chip">'+h(s.area)+'</span><h2><a href="/shops/'+h(s.id)+'">'+h(s.name)+'</a></h2><p>'+h(s.address||'Address not available')+'</p><p class="retailer-evidence">'+icon('shield',16)+h(verificationLabel(s))+'</p>'+UI.button('Explore shop catalogue',{href:'/shops/'+s.id,icon:icon('arrow',17)})+directions(s),{className:'directory-card'})).join('')+'</div><p class="directory-note">Shop details come from published listings. Confirmation time: Not available until stock is independently confirmed.</p>'+(S.error?empty('Directory unavailable',S.error):!shops.length?empty('No matching shops','Try another area, shop name or pincode.',UI.button('Reset filters',{attributes:'data-action="directory-reset"'})):'')+'</section>';}

function candidateShops(){return '<section class="shell section"><h2>Shops to contact</h2><p class="notice">These shops mention a relevant brand or category in their source. The exact model, price and stock have not been confirmed. Call before visiting.</p><div class="directory-grid">'+S.candidates.map(s=>'<article class="panel directory-card"><span class="badge area-chip">'+h(s.area)+'</span><h3><a href="/shops/'+h(s.id)+'">'+h(s.name)+'</a></h3><p>'+h(s.address||'Not available')+'</p><p>'+h(verificationLabel(s))+'</p><span class="badge stale">Not recently confirmed</span><p>Price: Not available | Distance: '+(s.distance==null?'Not available':s.distance.toFixed(1)+' km')+'</p>'+(s.phone?'<a class="button" href="tel:'+h(s.phone.replace(/[^+0-9]/g,''))+'">'+icon('phone',18)+'Call published number</a>':'<p>Phone: Not available</p>')+directions(s)+(s.source_url?'<a class="source-link" href="'+h(s.source_url)+'" target="_blank" rel="noopener noreferrer">Shop information source</a>':'')+'</article>').join('')+'</div></section>';}

function resultTabs(){return '<div class="results-tabs" role="group" aria-label="Result type">'+[['shops','Shop catalogues',S.assignmentShopCount],['confirmed','Confirmed stock',S.listings.length],['products','Product variants',S.products.length]].map(([key,label,count])=>'<button type="button" data-results-view="'+key+'" aria-pressed="'+(S.resultView===key)+'">'+label+' <span>'+count+'</span></button>').join('')+'</div>';}
async function loadShopAssignments(){const rid=S.shopAssignmentsRequest=(S.shopAssignmentsRequest||0)+1;S.shopAssignmentsHtml='';try{const query=new URLSearchParams({shop:entityId});if(S.shopQuery)query.set('q',S.shopQuery);const data=await api('simulation?'+query);if(rid!==S.shopAssignmentsRequest)return;if(data.available){const {shopAssignmentContent}=await import('./simulation.mjs?v=20261017-buyer-3');if(rid===S.shopAssignmentsRequest)S.shopAssignmentsHtml=shopAssignmentContent(data,query);}}catch{}}

function closeSuggestions(){suggestionIndex=-1;const box=$('#suggestions'),input=$('#product-search');if(box)box.hidden=true;if(input){input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');}}
function availableProducts(shopId){const existing=new Set((S.workspace?.listings||[]).filter(l=>l.shop_id===shopId).map(l=>l.product_id));return S.catalogue.filter(p=>!existing.has(p.id));}
